                        return null;
                    }
                    if ((!helpers.asciiCaseEql(content[(pos - 3)..pos], "www"))) {
                        return null;
                    }
                    const beg = (pos - 3);
                    if ((!checkLeftBoundary(content, beg, allow_emph))) {
                        return null;
                    }
                    var end = (pos + 1);
                    _ = &end;
                    const host = scanUrlComponent(content, end, 0, 46, ".-_", 1, 0);
                    if ((!host.ok)) {
                        return null;
                    }
                    end = host.end;
                    const path = scanUrlComponent(content, end, 47, 47, "/.-_~*+%", 0, 47);
                    end = path.end;
                    const query = scanUrlComponent(content, end, 63, 38, "&.-+_=()~*%", 1, 0);
                    end = query.end;
                    const frag = scanUrlComponent(content, end, 35, 0, ".-+_~*%", 1, 0);
                    end = frag.end;
                    end = postProcessAutolinkEnd(content, beg, end);
                    if ((!checkRightBoundary(content, end, allow_emph))) {
                        return null;
                    }
                    return .{ .beg = beg, .end = end };
                }
            }
        }
        return null;
}

pub fn postProcessAutolinkEnd(content: []const u8, beg: usize, end_in: usize) usize {
        var end = end_in;
        _ = &end;
        if (((end > beg) and (content[@as(usize, @intCast((end - 1)))] == 59))) {
            var j = (end - 2);
            _ = &j;
            while (((j > beg) and helpers.isAlphaNum(content[@as(usize, @intCast(j))]))) {
                j = (j - 1);
            }
            if (((j >= beg) and (content[@as(usize, @intCast(j))] == 38))) {
                end = j;
            }
        }
        if ((((end < content.len) and (content[@as(usize, @intCast(end))] == 59)) and (end > beg))) {
            var j = (end - 1);
            _ = &j;
            while (((j > beg) and helpers.isAlphaNum(content[@as(usize, @intCast(j))]))) {
                j = (j - 1);
            }
            if (((j >= beg) and (content[@as(usize, @intCast(j))] == 38))) {
                end = j;
            }
        }
        while (((end > beg) and (content[@as(usize, @intCast((end - 1)))] == 41))) {
            var open: i32 = 0;
            _ = &open;
            var close: i32 = 0;
            _ = &close;
            for (cp_iter_slice(content[beg..end])) |ch| {
                _ = &ch;
                if ((ch == 40)) {
                    open = (open + 1);
                }
                if ((ch == 41)) {
                    close = (close + 1);
                }
            }
            if ((close > open)) {
                end = (end - 1);
            } else {
                break;
            }
        }
        return end;
}
